function biggestAfterFill(grid: number[][]): number {
  const n = grid.length;
  const measure = (sr: number, sc: number): number => {
    const seen = grid.map(row => row.map(() => false));
    const stack = [[sr, sc]];
    seen[sr][sc] = true;
    let count = 0;
    while (stack.length) {
      const [r, c] = stack.pop()!;
      count++;
      for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        const nr = r + dr, nc = c + dc;
        if (nr >= 0 && nc >= 0 && nr < n && nc < n && !seen[nr][nc] && grid[nr][nc] === 1) {
          seen[nr][nc] = true;
          stack.push([nr, nc]);
        }
      }
    }
    return count;
  };
  let best = 0, water = false;
  for (let r = 0; r < n; r++)
    for (let c = 0; c < n; c++) {
      if (grid[r][c] === 0) {
        water = true;
        grid[r][c] = 1;
        best = Math.max(best, measure(r, c));
        grid[r][c] = 0;
      }
    }
  return water ? best : n * n;
}

