function biggestAfterFill(grid: number[][]): number {
  const n = grid.length;
  const id = grid.map(row => row.map(() => 0));
  const size = [0];
  const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  for (let r = 0; r < n; r++)
    for (let c = 0; c < n; c++) {
      if (grid[r][c] !== 1 || id[r][c]) continue;
      const label = size.length;
      let count = 0;
      const stack = [r * n + c];
      id[r][c] = label;
      while (stack.length) {
        const cell = stack.pop()!, cr = Math.floor(cell / n), cc = cell % n;
        count++;
        for (const [dr, dc] of dirs) {
          const nr = cr + dr, nc = cc + dc;
          if (nr >= 0 && nc >= 0 && nr < n && nc < n && grid[nr][nc] === 1 && !id[nr][nc]) {
            id[nr][nc] = label;
            stack.push(nr * n + nc);
          }
        }
      }
      size.push(count);
    }
  let best = Math.max(...size);
  let water = false;
  for (let r = 0; r < n; r++)
    for (let c = 0; c < n; c++) {
      if (grid[r][c] !== 0) continue;
      water = true;
      const near = new Set<number>();
      for (const [dr, dc] of dirs) {
        const nr = r + dr, nc = c + dc;
        if (nr >= 0 && nc >= 0 && nr < n && nc < n && id[nr][nc]) near.add(id[nr][nc]);
      }
      let total = 1;
      for (const k of near) total += size[k];
      best = Math.max(best, total);
    }
  return water ? best : n * n;
}

